+namespace sv_246dd5fb904746c88f64774e5e6f6a3b.Services;
+
+/// <summary>
+/// Scoped service that provides low-stock alert counts and coordinates polling notifications.
+/// Because it is scoped, each circuit (user) has its own instance with independent state.
+/// </summary>
+public class InventoryAlertService : IDisposable
+{
+    private readonly Random _random = new();
+    private Timer? _timer;
+    private int _subscriberCount;
+    private string _warehouseId = string.Empty;
+
+    public int CurrentLowStockCount { get; private set; }
+
+    /// <summary>
+    /// Fired whenever new alert data arrives from polling. All subscribed components should refresh.
+    /// </summary>
+    public event Func<Task>? OnAlertDataChanged;
+
+    /// <summary>
+    /// Simulates a database query returning the number of low-stock items for a warehouse.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        return Task.FromResult(_random.Next(0, 16));
+    }
+
+    /// <summary>
+    /// Starts polling every 10 seconds for the given warehouse. Reference-counted so multiple
+    /// subscribers share the same timer; polling stops only when all unsubscribe.
+    /// </summary>
+    public void StartPolling(string warehouseId)
+    {
+        _warehouseId = warehouseId;
+        _subscriberCount++;
+
+        if (_timer is null)
+        {
+            _timer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+        }
+    }
+
+    /// <summary>
+    /// Decrements subscribers; stops polling when none remain.
+    /// </summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+
+        if (_subscriberCount == 0)
+        {
+            _timer?.Dispose();
+            _timer = null;
+        }
+    }
+
+    /// <summary>
+    /// Updates the warehouse being polled (e.g., when user switches warehouse while polling is active).
+    /// </summary>
+    public void UpdateWarehouse(string warehouseId)
+    {
+        _warehouseId = warehouseId;
+    }
